SELECT CASE WHEN w.entry_quality_score >= 70 THEN '70+' WHEN w.entry_quality_score >= 60 THEN '60-69' WHEN w.entry_quality_score >= 55 THEN '55-59' ELSE '50-54' END AS eq_band, CASE WHEN s.atr_percent < 0.1667 THEN 'ATR<0.1667' WHEN s.atr_percent < 0.25 THEN 'ATR0.1667-0.25' ELSE 'ATR>=0.25' END AS atr_band, COUNT(*) AS n, SUM(pp.realized_pnl < 0) AS losers, SUM(pp.status = 'STOPPED') AS stopped, AVG(pp.realized_pnl / NULLIF(pp.entry_price * pp.quantity, 0) * 100) AS avg_pnl_pct, SUM(pp.realized_pnl) AS net_pnl FROM crypto_ai.paper_position pp JOIN crypto_ai.wallet_managed_position w ON w.symbol = pp.symbol AND w.opened_at BETWEEN pp.opened_at - INTERVAL 15 SECOND AND pp.opened_at + INTERVAL 15 SECOND JOIN crypto_ai.trade_signal s ON s.id = pp.signal_id WHERE pp.status IN ('CLOSED','STOPPED') GROUP BY eq_band, atr_band ORDER BY eq_band, atr_band LIMIT 20